// Helper function to calculate the sum of odd elements at even positions
function SumOddElementsInEvenPositions(lst: seq<int>): int
    requires |lst| > 0  // the list must be non-empty
{
    var sum := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst|  // ensure i is within bounds
        invariant sum == SumOddElementsInEvenPositions(lst[0..i])  // sum is correct up to index i
    {
        if i % 2 == 0 && lst[i] % 2 != 0 {
            sum := sum + lst[i];
        }
        i := i + 1;
    }
    return sum;
}
